  message += ' Check your connection and try again.';
} else if (status === 429) {
  message += ' The public demo is rate limited; please retry later.';
} else if (status >= 500) {
  message += ' The public demo service is temporarily unavailable; please retry.';
} else {
  message += ' The service returned HTTP ' + status + '; please retry.';
}
return this.makeError(context, message, 'REQUEST_FAILED', status);

status = status === undefined ? 'available' : status;
if (['available', 'pending', 'sold'].indexOf(status) === -1) {
  return this.$q.reject(this.makeError('pets', 'Choose available, pending or sold.', 'INVALID_STATUS', 0));
}
const generation = this.generation;
const selection = ++this.selection;
const changed = this.currentStatus !== status;
this.currentStatus = status;
this.error = null;
