  this.lastUpdated = null;
}
const cached = this.statusCache[status];
// Prefer an existing refresh over an older cached value.
let request = this.statusRequests[status];
if (!request && !force && this.fresh(cached)) {
  this.pets = cached.value;
  this.lastUpdated = cached.time;
  this.loading = false;
  return this.$q.when(cached.value);
}
