    if (this.generation === generation) {
      this.statusCache[status] = entry;
    }
    return entry;
  }).catch(err => {
    throw this.requestError(err, 'pets:' + status, status + ' pets');
  }).finally(() => {
    if (this.generation === generation && this.statusRequests[status] === request) {
      delete this.statusRequests[status];
    }
  });
  this.statusRequests[status] = request;
}
// Every caller has a selection token, even when sharing the same network request.
