  if (this.generation === generation && this.selection === selection) {
    this.pets = entry.value;
    this.lastUpdated = entry.time;
  }
  return entry.value;
}, err => {
  if (this.generation === generation && this.selection === selection) {
    this.error = err.message;
  }
  throw err;
}).finally(() => {
  if (this.generation === generation && this.selection === selection) {
    this.loading = false;
  }
});

if (this.inventoryRequest) {
  return this.inventoryRequest;
}
this.inventoryError = null;
if (!force && this.fresh(this.inventoryCache)) {
  this.inventory = this.inventoryCache.value;
  this.inventoryLoading = false;
  return this.$q.when(this.inventory);
}
const generation = this.generation;
this.inventoryLoading = true;
const request = this.$q.when().then(() => this.petstoreApi.getInventory()).then(response => {
  const value = this.normalizeInventory(response.data);
  if (this.generation === generation) {
