}).finally(() => {
  if (this.generation === generation && this.inventoryRequest === request) {
    this.inventoryLoading = false;
    this.inventoryRequest = null;
  }
});
this.inventoryRequest = request;
return request;

if (!this.validId(id)) {
  return this.$q.reject(this.makeError('pet', 'A valid integer pet ID is required.', 'INVALID_ID', 0));
