  return this.$q.when(cached.value);
}
const generation = this.generation;
this.detailLoading[key] = true;
const request = this.$q.when().then(() => this.petstoreApi.getPetById({ petId: id })).then(response => {
  const pet = this.normalizePet(response.data);
  if (!pet) {
    throw this.makeError('pet:' + key, 'The pet service returned an invalid pet record.', 'INVALID_RESPONSE', 0);
  }
  if (this.generation === generation) {
    this.detailCache[key] = { value: pet, time: Date.now() };
  }
  return pet;
