  }
  throw error;
}).finally(() => {
  if (this.generation === generation && this.detailRequests[key] === request) {
    this.detailLoading[key] = false;
    delete this.detailRequests[key];
  }
});
this.detailRequests[key] = request;
return request;

// Epoch invalidation prevents pre-clear requests from touching newer state or pending maps.
this.generation += 1;
